/* Svenska årskurs 5, units 1–6: Kartan i vinden (och, men, för, så), Fakta: Vargen (adjektivets former),
   Den största pumpan (stor, större, störst), Loppisen (min, mitt, mina), Fakta: Planeterna (bestämd form),
   Stormen (verbet på plats 2 efter tidsord). Yasmin, Leo and Kexi in 5A at Björkskolan, teacher Karin. */
import {defineUnit, word, t3, L, A, R, qt, pick, shuffle, svLines, boxes, pic, kid} from "../svenska/unit";
