word("pumpa", {sv: "pumpa (en)", m: "pump(a|an|or|orna)", d: say("En stor, rund och ofta orange grönsak som växer på marken.", "A big, round, often orange vegetable that grows on the ground.", "خضار كبيرة مستديرة، برتقالية غالبًا، تنمو على الأرض."), ex: "Av pumpan gjorde morfar en god soppa.", tr: {en: "pumpkin", ar: "يقطين"}, gap: ["Av", "pumpan", "gjorde morfar en god soppa."], gapForm: "pumpan", form: "en pumpa – pumpor"});
word("fro", {sv: "frö (ett)", m: "frö(et|n|na)?", d: say("Ett litet korn som en ny växt kan växa upp ur.", "A small grain that a new plant can grow from.", "حبّة صغيرة يمكن أن تنمو منها نبتة جديدة."), ex: "De satte ett litet frö i jorden.", tr: {en: "seed", ar: "بذرة"}, gap: ["De satte ett litet", "frö", "i jorden."], gapForm: "frö", form: "ett frö – frön"});
word("odla", {sv: "odla", m: "odla(r|de|t)?", d: say("Så och ta hand om växter så att de växer.", "Sow and take care of plants so that they grow.", "أن تزرع النباتات وتعتني بها حتى تنمو."), ex: "Morfar odlar tomater och pumpor.", tr: {en: "grow (plants)", ar: "يزرع"}, syn: ["plantera"], wrong: ["jaga", "läsa"], gap: ["Morfar tycker om att", "odla", "tomater och pumpor."], gapForm: "odla", form: "odla – odlade – har odlat"});
word("vattna", {sv: "vattna", m: "vattna(r|de|t)?", d: say("Ge vatten till växter.", "Give water to plants.", "أن تسقي النباتات بالماء."), ex: "Varje morgon vattnade de krukan.", tr: {en: "water (plants)", ar: "يسقي"}, gap: ["Glöm inte att", "vattna", "blommorna när det är varmt!"], gapForm: "vattna", form: "vattna – vattnade – har vattnat"});
word("gro", {sv: "gro", m: "gro(r|dde)?", d: say("När ett frö börjar växa och ett litet grönt skott kommer upp.", "When a seed starts to grow and a small green shoot comes up.", "عندما تبدأ البذرة في النمو ويخرج منها برعم أخضر صغير."), ex: "Fröet hade börjat gro.", tr: {en: "sprout", ar: "ينبُت"}, syn: ["börja växa"], wrong: ["vissna", "frysa"], gap: ["Efter en vecka började fröet", "gro", "."], gapForm: "gro", form: "gro – grodde – har grott"});
word("skorda", {sv: "skörda", m: "skörda(r|de|t)?", d: say("Ta in det som har vuxit, när det är färdigt.", "Bring in what has grown, when it is ready.", "أن تجمع ما نما عندما يصبح جاهزًا."), ex: "I september var det dags att skörda.", tr: {en: "harvest", ar: "يحصد"}, syn: ["plocka"], opp: ["så"], wrong: ["sova", "springa"], gap: ["När äpplena är mogna är det dags att", "skörda", "dem."], gapForm: "skörda", form: "skörda – skördade – har skördat"});
word("tavla", {sv: "tävla", m: "tävla(r|de|t)?", d: say("Försöka vara bättre än andra för att vinna.", "Try to be better than others in order to win.", "أن تحاول أن تكون أفضل من الآخرين لكي تفوز."), ex: "Klasserna tävlade om den största pumpan.", tr: {en: "compete", ar: "يتنافس"}, gap: ["Klasserna ska", "tävla", "om vem som har den största pumpan."], gapForm: "tävla", form: "tävla – tävlade – har tävlat"});
word("vaga", {sv: "väga", m: "väg(a|er|de|t)", d: say("Ta reda på hur tung något är. Eller: vara så tung.", "Find out how heavy something is. Or: be that heavy.", "أن تعرف كم يبلغ ثِقل شيء. أو: أن يكون ثقله كذا."), ex: "Pumpan vägde elva kilo.", tr: {en: "weigh", ar: "يزن"}, gap: ["Vi lägger pumpan på vågen för att", "väga", "den."], gapForm: "väga", form: "väga – vägde – har vägt"});
word("svkomparativ", {sv: "komparativ", m: "komparativ(en|et)?", d: say("Formen som jämför två saker: större, snabbare.", "The form that compares two things: större, snabbare.", "الصيغة التي تقارن بين شيئين: större، snabbare."), ex: "Ibrahims pumpa var större än Elsas.", tr: {en: "comparative", ar: "صيغة المقارنة"}});
word("svsuperlativ", {sv: "superlativ", m: "superlativ(en|et)?", d: say("Formen som säger att något är mest av alla: störst, snabbast.", "The form that says something is the most of all: störst, snabbast.", "الصيغة التي تقول إن الشيء هو الأكثر بين الجميع: störst، snabbast."), ex: "Yasmins och Leos pumpa var störst.", tr: {en: "superlative", ar: "صيغة التفضيل العليا"}});
