word("planet", {sv: "planet (en)", m: "planet(en|er|erna)?", d: say("Ett stort klot i rymden som går runt en stjärna. Jorden är en planet.", "A big ball in space that goes around a star. The Earth is a planet.", "جِرم كبير في الفضاء يدور حول نجم. الأرض كوكب."), ex: "Mars kallas den röda planeten.", tr: {en: "planet", ar: "كوكب"}, gap: ["Mars kallas den röda", "planeten", "."], gapForm: "planeten", form: "en planet – planeter"});
