word("astronaut", {sv: "astronaut (en)", m: "astronaut(en|er|erna)?", d: say("En person som reser ut i rymden.", "A person who travels into space.", "شخص يسافر إلى الفضاء."), ex: "Yasmin vill bli astronaut.", tr: {en: "astronaut", ar: "رائد فضاء"}, gap: ["Yasmin vill bli", "astronaut", "och flyga till Mars."], gapForm: "astronaut", form: "en astronaut – astronauter"});
word("raket", {sv: "raket (en)", m: "raket(en|er|erna)?", d: say("En farkost som kan flyga mycket snabbt upp i rymden.", "A craft that can fly very fast up into space.", "مَركبة تطير بسرعة كبيرة إلى الفضاء."), ex: "Astronauterna flög till månen med en raket.", tr: {en: "rocket", ar: "صاروخ"}, gap: ["Astronauterna flög till månen med en stor", "raket", "."], gapForm: "raket", form: "en raket – raketer"});
word("teleskop", {sv: "teleskop (ett)", m: "teleskop(et|en)?", d: say("Ett rör med glas i som gör att saker långt borta ser ut att vara nära.", "A tube with glass lenses that makes things far away look near.", "أنبوب فيه عدسات يجعل الأشياء البعيدة تبدو قريبة."), ex: "Med teleskopet kunde Leo se planeten.", tr: {en: "telescope", ar: "مِقراب (تلسكوب)"}, gap: ["Med", "teleskopet", "kunde Leo se månens berg."], gapForm: "teleskopet", form: "ett teleskop – teleskop"});
word("svavstand", {sv: "avstånd (ett)", m: "avstånd(et|en)?", d: say("Hur långt det är mellan två saker.", "How far it is between two things.", "كم تبلغ المسافة بين شيئين."), ex: "Avståndet mellan planeterna är enormt.", tr: {en: "distance", ar: "مسافة"}, syn: ["sträcka"], wrong: ["vikt", "färg"], gap: ["Mellan jorden och solen är det ett mycket långt", "avstånd", "."], gapForm: "avstånd", form: "ett avstånd – avstånd"});
